// canteen.js: EP8's set and props (Stage 2). The school canteen at recess (BG.canteen), the noodle stall close-up (BG.stall), under the
// table (BG.under); the three containers, the spoon, the sand pile, the ceramic bowl and its soup spoon, the white canvas school shoe,
// the school T-shirt, the wooden pencil; THE 7 MATERIALS board with its tiles and source slots. Pure functions of their arguments.
// World: the table top runs y 742 (back edge) .. 892 (front edge); things on the table stand at TY = 846. The floor in front: y 1066.
const XDEFS5 = () => `${lg("cSky", [[0, "#8FD0FF"], [1, "#E6F6FF"]])}${lg("cFloor", [[0, "#E4DBCB"], [1, "#C2B49E"]])}${lg("cTable", [[0, "#FCF8EE"], [1, "#EDE3CF"]])}
  ${lg("cSteel", [[0, "#F6F8FB"], [.42, "#C6CED8"], [.58, "#98A4B2"], [1, "#DDE3EA"]])}${lg("cSteelH", [[0, "#AEB8C4"], [.3, "#F4F7FA"], [.6, "#B4BECA"], [1, "#8E9AA8"]], 1, 0)}
  ${lg("cWood", [[0, "#D39A62"], [1, "#A9713F"]])}${lg("cWoodD", [[0, "#9A6436"], [1, "#7A4C26"]])}${lg("cSand", [[0, "#F6E6B4"], [1, "#DDBF7C"]])}
  ${lg("cGlass", [[0, "#DCF1FF", .5], [.35, "#fff", .1], [.7, "#fff", .04], [1, "#BFE0F4", .45]], 1, 0)}${lg("cLouv", [[0, "#E8F7FF"], [.5, "#A9D6EE"], [1, "#7DB6D4"]])}
  ${lg("cPink", [[0, "#F58DB0"], [1, "#DC4F82"]])}${lg("cBowl", [[0, "#FFFFFF"], [1, "#DDE3EE"]])}${lg("cBowlIn", [[0, "#C9D2E2"], [1, "#F4F7FB"]])}${lg("cCanvas", [[0, "#FFFFFF"], [1, "#E8ECF4"]])}
  ${lg("cWall", [[0, "#FBF4E4"], [1, "#EFE2C6"]])}${lg("cRoof", [[0, "#EDE6DA"], [1, "#FAF6EE"]])}${lg("cBark", [[0, "#8E8376"], [.5, "#A79C8C"], [1, "#74695C"]], 1, 0)}
  ${lg("jTree", [[0, "#2E1C10", .9], [.6, "#6B4420", .5], [1, "#C8923A", .5]], 1, .2)}<pattern id="cWeave" width="8" height="8" patternUnits="userSpaceOnUse"><path d="M0 2 H8 M0 6 H8 M2 0 V8 M6 0 V8" stroke="#8D97B2" stroke-width="1" opacity=".22"/></pattern>
  <clipPath id="cRing"><circle cx="430" cy="470" r="172"/></clipPath>`;
const TY = 846, FLOORY = 1066;

/* ---------- small building blocks ---------- */
// a glass louvre window: an aluminium frame with n slanted glass blades (origin = top left)
function louvre(x, y, w, h, n = 6, o = {}) { const bh = h / n; let s = `<rect x="${x - 6}" y="${y - 6}" width="${w + 12}" height="${h + 12}" rx="4" fill="#C9D2DC" stroke="#8E9AA8" stroke-width="${o.sw || 3}"/><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="#4F6F86"/>`;
  for (let i = 0; i < n; i++) s += `<path d="M${x} ${n2(y + i * bh + bh * .12)} H${x + w} V${n2(y + i * bh + bh * .98)} H${x}z" fill="url(#cLouv)"/><path d="M${x + w * .08} ${n2(y + i * bh + bh * .3)} H${x + w * .5}" stroke="#fff" stroke-width="${n2(bh * .12)}" stroke-linecap="round" opacity=".7"/>`;
  return s + `<rect x="${x + w / 2 - 3}" y="${y}" width="6" height="${h}" fill="#C9D2DC"/>`; }
// wood grain lines along a plank from x0 to x1 at height y (seeded)
const wgrain = (x0, x1, y, n, seed = 1, col = "#7A4C26", o = .45) => { let s = ""; for (let i = 0; i < n; i++) { const a = x0 + (x1 - x0) * hash(i, seed), len = (x1 - x0) * (.12 + .25 * hash(i, seed + 3)), yy = y + (hash(i, seed + 5) - .5) * 2; s += `<path d="M${n2(a)} ${n2(yy)} q${n2(len / 2)} ${n2(-3 + 6 * hash(i, seed + 7))} ${n2(len)} 0" fill="none" stroke="${col}" stroke-width="2" stroke-linecap="round" opacity="${o}"/>`; } return s; };
const steam = (t, x, y, k = 1) => [0, 1, 2].map((i) => { const v = ((t * .35 + i / 3) % 1); return `<path d="M${n2(x + (i - 1) * 22 * k)} ${n2(y - 70 * v * k)} q${n2(12 * k)} ${n2(-18 * k)} 0 ${n2(-36 * k)} q${n2(-12 * k)} ${n2(-18 * k)} 0 ${n2(-36 * k)}" fill="none" stroke="#fff" stroke-width="${n2(7 * k)}" stroke-linecap="round" opacity="${n2(.55 * Math.sin(Math.PI * v))}"/>`; }).join("");

/* ---------- the canteen (static, baked): open-sided school canteen, noodle stall left, drinks stall right, the classroom block behind ---------- */
function ceilingFan(x, y, a = 0) { return `<rect x="${x - 4}" y="${y - 70}" width="8" height="70" fill="#9AA6B4"/><ellipse cx="${x}" cy="${y}" rx="22" ry="9" fill="#DDE3EA" stroke="#8E9AA8" stroke-width="3"/>${[0, 120, 240].map((d) => { const an = (d + a) * Math.PI / 180, c = Math.cos(an), s = Math.sin(an) * .22; return `<path d="M${x} ${y} L${n2(x + c * 150 - s * 60)} ${n2(y + s * 150 - 8)} L${n2(x + c * 150 + s * 60)} ${n2(y + s * 150 + 10)}z" fill="#F4F7FA" stroke="#8E9AA8" stroke-width="3" stroke-linejoin="round"/>`; }).join("")}`; }
function classBlock() { let s = `<rect x="430" y="118" width="1080" height="500" fill="url(#cWall)"/><rect x="430" y="104" width="1080" height="20" fill="#E0705A"/>`;
  for (let f = 0; f < 3; f++) { const y = 150 + f * 150; s += `<rect x="430" y="${y}" width="1080" height="104" fill="#E6D8BC"/>`;
    for (let c = 0; c < 6; c++) { const x = 470 + c * 176; s += c % 3 === 2 ? `<rect x="${x + 28}" y="${y + 8}" width="70" height="96" fill="#4E93B4"/><rect x="${x + 40}" y="${y + 18}" width="46" height="34" rx="3" fill="#BFE0F4"/>` : louvre(x, y + 14, 126, 70, 5, { sw: 2 }); }
    s += `<rect x="430" y="${y + 104}" width="1080" height="46" fill="#FBF4E4"/><rect x="430" y="${y + 104}" width="1080" height="9" fill="#2EA3A0"/><rect x="430" y="${y + 142}" width="1080" height="8" fill="#D9C8A4"/>`; }
  for (let c = 0; c <= 6; c++) s += `<rect x="${448 + c * 176 - 8}" y="118" width="16" height="500" fill="#F6ECD6"/>`;
  return s; }
BG.canteen = () => { const r = rndm(8); let far = "", tiles = "", bowls = "", cups = "", bottles = "";
  // far: the sky, a rain tree, the classroom block (hazy)
  far += `<rect x="-192" y="-108" width="2304" height="800" fill="url(#cSky)"/><g filter="url(#b2)">${classBlock()}<g>${[[330, 330, 150], [250, 250, 120], [400, 240, 110], [1600, 300, 150], [1700, 220, 120], [1540, 210, 100]].map(([x, y, rr], i) => `<circle cx="${x}" cy="${y}" r="${rr}" fill="${i % 2 ? "#5BB86E" : "#4BA862"}"/>`).join("")}<rect x="318" y="380" width="30" height="240" fill="#7A5A3E"/><rect x="1606" y="360" width="30" height="260" fill="#7A5A3E"/></g>
    <rect x="-192" y="560" width="2304" height="60" fill="#8FD07A"/></g><rect x="-192" y="-108" width="2304" height="800" fill="#fff" opacity=".12"/>`;
  // the floor: big pale tiles in perspective
  let floor = `<rect x="-192" y="604" width="2304" height="600" fill="url(#cFloor)"/>`; for (let i = -14; i <= 14; i++) floor += `<path d="M${960 + i * 70} 604 L${960 + i * 260} 1200" stroke="#A8998A" stroke-width="2" opacity=".5"/>`;
  [612, 628, 652, 688, 742, 822, 940, 1110].forEach((y) => { floor += `<path d="M-192 ${y} H2112" stroke="#A8998A" stroke-width="2" opacity=".5"/>`; });
  // far tables with benches, pupils' bottles
  const farTable = (x, y, k) => `<g transform="translate(${x} ${y}) scale(${k})"><ellipse cx="0" cy="96" rx="330" ry="16" fill="${P.ink}" opacity=".14"/><rect x="-300" y="52" width="600" height="14" rx="5" fill="url(#cWood)" stroke="#7A4C26" stroke-width="2.5"/><path d="M-270 66 V96 M270 66 V96" stroke="#8E9AA8" stroke-width="8"/><rect x="-320" y="0" width="640" height="20" rx="6" fill="url(#cTable)" stroke="#B9A98C" stroke-width="3"/><path d="M-290 20 V92 M290 20 V92" stroke="#8E9AA8" stroke-width="10"/><rect x="-306" y="-26" width="612" height="12" rx="5" fill="url(#cWood)" stroke="#7A4C26" stroke-width="2.5"/></g>`;
  const farT = farTable(760, 610, .5) + farTable(1190, 610, .5) + farTable(960, 648, .74)
    + `<g transform="translate(900 640)"><rect x="-9" y="-30" width="18" height="30" rx="5" fill="#2EC4B6"/><rect x="-5" y="-38" width="10" height="9" rx="2" fill="#fff"/></g><g transform="translate(1040 640)"><rect x="-22" y="-16" width="44" height="16" rx="4" fill="#FF8FB1"/></g>`;
  // pillars, the roof slab with beams, hanging fans, a string of school bunting
  const pillar = (x) => `<rect x="${x - 34}" y="-108" width="68" height="760" fill="#FBF7EE"/><rect x="${x - 34}" y="-108" width="16" height="760" fill="#fff"/><rect x="${x + 18}" y="-108" width="16" height="760" fill="#E3DACA"/><rect x="${x - 38}" y="520" width="76" height="132" fill="#2EA3A0"/><rect x="${x - 38}" y="520" width="76" height="12" fill="#57C4BE"/>`;
  const roof = `<rect x="-192" y="-108" width="2304" height="176" fill="url(#cRoof)"/><rect x="-192" y="58" width="2304" height="26" fill="#DCD3C4"/>${[-60, 480, 1440, 1980].map((x) => `<rect x="${x - 20}" y="-108" width="40" height="170" fill="#E6DED0"/>`).join("")}` + ceilingFan(760, 150, 20) + ceilingFan(1180, 150, 80)
    + `<path d="M500 96 Q960 150 1420 96" fill="none" stroke="#8E9AA8" stroke-width="2.5"/>${Array.from({ length: 11 }, (_, i) => { const u = (i + .5) / 11, x = 500 + 920 * u, y = 96 + 54 * 4 * u * (1 - u) * .5 + 1; return `<path d="M${n2(x - 20)} ${n2(y)} L${n2(x + 20)} ${n2(y)} L${n2(x)} ${n2(y + 42)}z" fill="${["#FF8FB1", "#57C4BE", "#FFB38A", "#B9A6FF"][i % 4]}"/>`; }).join("")}`;
  // the noodle stall (left): a signboard, menu pictures, a steel counter with a glass guard, stacked ceramic bowls, soup spoons, a big pot
  for (let i = 0; i < 4; i++) for (let j = 0; j < 4 - (i % 2); j++) bowls += `<g transform="translate(${96 + i * 78} ${444 - j * 13})"><path d="M-32 -12 Q-28 10 -10 12 H10 Q28 10 32 -12z" fill="url(#cBowl)" stroke="#9AA6C0" stroke-width="2.5"/><path d="M-32 -12 H32" stroke="#2F6FCB" stroke-width="4" stroke-linecap="round"/></g>`;
  const noodle = `<rect x="-192" y="84" width="650" height="560" fill="#5E4A3A"/><rect x="-192" y="250" width="650" height="210" fill="#3E2F26"/>
    <rect x="-150" y="270" width="150" height="14" rx="4" fill="#8E9AA8"/><g transform="translate(-76 268)"><path d="M-56 -70 H56 L50 0 H-50z" fill="url(#cSteel)" stroke="#6E7A88" stroke-width="3"/><ellipse cx="0" cy="-70" rx="58" ry="10" fill="#DDE3EA" stroke="#6E7A88" stroke-width="3"/><path d="M-70 -50 h14 M56 -50 h14" stroke="#6E7A88" stroke-width="7" stroke-linecap="round"/></g>
    <rect x="-192" y="96" width="650" height="130" fill="#D8452E"/><rect x="-192" y="96" width="650" height="14" fill="#F06A4E"/><rect x="-192" y="214" width="650" height="12" fill="#A8301E"/>${T(150, 186, "NOODLES", 84, "#FFF3DC", { ls: 10 })}
    ${[[-20, "#F2C27A"], [120, "#E8A45A"], [260, "#F0D09A"]].map(([x, c], i) => `<g transform="translate(${x} 236)"><rect x="0" y="0" width="120" height="84" rx="8" fill="#FFF8EA" stroke="#C9A772" stroke-width="3"/><ellipse cx="60" cy="50" rx="40" ry="18" fill="#fff" stroke="#2F6FCB" stroke-width="3"/><ellipse cx="60" cy="46" rx="30" ry="10" fill="${c}"/><circle cx="${48 + i * 8}" cy="43" r="5" fill="${i === 1 ? "#E0705A" : "#6FBF5A"}"/></g>`).join("")}
    <rect x="-192" y="370" width="650" height="92" fill="#BFE6FF" opacity=".22"/><rect x="-192" y="366" width="650" height="6" fill="#DDE3EA"/><path d="M-100 380 L-40 452 M200 380 L260 452" stroke="#fff" stroke-width="5" opacity=".35"/>
    ${bowls}<g transform="translate(398 452)"><rect x="-22" y="-44" width="44" height="44" rx="8" fill="url(#cSteel)" stroke="#6E7A88" stroke-width="3"/>${[-12, -2, 9].map((x, i) => `<path d="M${x} -40 L${x + (i - 1) * 6} -84" stroke="#fff" stroke-width="9" stroke-linecap="round"/><path d="M${x} -40 L${x + (i - 1) * 6} -84" stroke="#C9D2E2" stroke-width="2"/>`).join("")}</g>
    <rect x="-192" y="456" width="664" height="26" rx="4" fill="url(#cSteel)" stroke="#6E7A88" stroke-width="3"/><rect x="-192" y="482" width="650" height="170" fill="#F4F7FA"/>${Array.from({ length: 9 }, (_, i) => `<rect x="${-192 + i * 72}" y="${482 + (i % 2) * 0}" width="72" height="56" fill="${i % 2 ? "#2EA3A0" : "#F4F7FA"}"/><rect x="${-192 + i * 72}" y="538" width="72" height="56" fill="${i % 2 ? "#F4F7FA" : "#2EA3A0"}"/>`).join("")}<rect x="-192" y="594" width="650" height="58" fill="#DCE6EA"/>`;
  // the drinks stall (right): a signboard, a drinks dispenser, cups, a fridge with bottles
  for (let i = 0; i < 6; i++) cups += `<g transform="translate(${1560 + i * 44} 452)"><path d="M-15 -44 H15 L11 0 H-11z" fill="#fff" opacity=".85" stroke="#9AA6C0" stroke-width="2.5"/><path d="M-13 -24 H13 L11 0 H-11z" fill="${["#F2A65A", "#8B5A3C", "#F7D774", "#F2A65A", "#E86A5A", "#8B5A3C"][i]}" opacity=".9"/><path d="M4 -44 L10 -66" stroke="#E8375A" stroke-width="4" stroke-linecap="round"/></g>`;
  for (let i = 0; i < 4; i++) for (let j = 0; j < 3; j++) bottles += `<g transform="translate(${1900 + i * 42} ${318 + j * 62})"><rect x="-11" y="-34" width="22" height="40" rx="6" fill="${["#F2A65A", "#7FD6E8", "#9BD77A", "#F58DB0"][(i + j) % 4]}"/><rect x="-6" y="-46" width="12" height="13" rx="3" fill="#fff"/></g>`;
  const drinks = `<rect x="1462" y="84" width="650" height="560" fill="#4A5A66"/><rect x="1462" y="250" width="650" height="210" fill="#33414C"/>
    <rect x="1462" y="96" width="650" height="130" fill="#1E8FA6"/><rect x="1462" y="96" width="650" height="14" fill="#48B6CC"/><rect x="1462" y="214" width="650" height="12" fill="#13687A"/>${T(1760, 186, "DRINKS", 84, "#FFF3DC", { ls: 10 })}
    <g transform="translate(1560 300)">${[0, 1].map((i) => `<g transform="translate(${i * 100} 0)"><rect x="-40" y="-40" width="80" height="120" rx="10" fill="#fff" opacity=".8" stroke="#9AA6C0" stroke-width="3"/><rect x="-36" y="0" width="72" height="76" rx="8" fill="${i ? "#F7D774" : "#F2A65A"}" opacity=".9"/><rect x="-44" y="-52" width="88" height="16" rx="6" fill="#33414C"/><rect x="-44" y="80" width="88" height="28" rx="5" fill="#33414C"/><rect x="-6" y="96" width="12" height="20" rx="3" fill="#DDE3EA"/></g>`).join("")}</g>
    <rect x="1868" y="262" width="260" height="196" rx="8" fill="#EAF4FF" stroke="#9AA6C0" stroke-width="4"/>${bottles}<path d="M1868 326 H2128 M1868 388 H2128" stroke="#9AA6C0" stroke-width="3"/>${cups}
    <rect x="1448" y="456" width="664" height="26" rx="4" fill="url(#cSteel)" stroke="#6E7A88" stroke-width="3"/><rect x="1462" y="482" width="650" height="170" fill="#F4F7FA"/>${Array.from({ length: 9 }, (_, i) => `<rect x="${1462 + i * 72}" y="482" width="72" height="56" fill="${i % 2 ? "#F4F7FA" : "#F2A65A"}"/><rect x="${1462 + i * 72}" y="538" width="72" height="56" fill="${i % 2 ? "#F2A65A" : "#F4F7FA"}"/>`).join("")}<rect x="1462" y="594" width="650" height="58" fill="#E6E0D6"/>`;
  // a tray-return rack by the right pillar
  const rack = `<g transform="translate(1368 652)"><rect x="-46" y="-150" width="92" height="150" rx="6" fill="#DDE3EA" stroke="#8E9AA8" stroke-width="4"/>${[-120, -84, -48].map((y) => `<rect x="-40" y="${y}" width="80" height="10" rx="3" fill="#E8375A"/><rect x="-40" y="${y + 10}" width="80" height="4" fill="#8E9AA8"/>`).join("")}${T(0, -160, "TRAYS", 20, "#4A5A66", { ls: 2 })}</g>`;
  // the long table in front, and the wooden bench in front of it
  const table = `<ellipse cx="960" cy="1076" rx="980" ry="40" fill="${P.ink}" opacity=".16" filter="url(#b10)"/><path d="M150 932 V1072 M1770 932 V1072" stroke="url(#cSteelH)" stroke-width="30"/><path d="M190 760 V930 M1730 760 V930" stroke="#8E9AA8" stroke-width="18" opacity=".5"/>
    <path d="M150 742 H1770 L1884 892 H36z" fill="url(#cTable)"/><path d="M150 742 H1770" stroke="#fff" stroke-width="4" opacity=".7"/><path d="M36 892 H1884 V920 Q1884 930 1874 930 H46 Q36 930 36 920z" fill="url(#cSteel)" stroke="#8E9AA8" stroke-width="3"/>
    <path d="M300 750 L230 884 M700 750 L660 884 M1220 750 L1260 884 M1620 750 L1690 884" stroke="#fff" stroke-width="26" opacity=".25"/>`;
  return far + floor + farT + pillar(480) + pillar(1440) + noodle + drinks + rack + roof + table + benchNear(); };
// the wooden bench in front of the table (seat top y 986..1030). Also drawn alone, close, for Part 2's wood scene
