  const top = `<path d="M-104 -204 Q-104 -242 -70 -242 Q-50 -242 -40 -230 L138 -130 L142 -98 L134 -98 L-84 -206z" fill="${hexL("#EEF2F8", "#FFE08A", tp)}" stroke="${LC}" stroke-width="5" stroke-linejoin="round"/>
    <path d="${up}" fill="${tp > .05 ? hexL("#FFFFFF", "#FFE08A", tp) : "url(#cCanvas)"}" stroke="${LC}" stroke-width="5" stroke-linejoin="round"/><path d="${up}" fill="url(#cWeave)"/>
    <path d="M-238 -60 Q-242 -150 -222 -192" fill="none" stroke="${LN}" stroke-width="2.5" stroke-dasharray="7 6"/><path d="M-196 -52 Q-150 -100 -112 -166" fill="none" stroke="${LN}" stroke-width="2.5" stroke-dasharray="7 6"/><path d="M-96 -172 L116 -66 Q132 -60 134 -50" fill="none" stroke="${LN}" stroke-width="2.5" stroke-dasharray="7 6"/>
    <path d="M-256 -170 Q-272 -186 -264 -206 Q-254 -216 -242 -208" fill="#EEF2F8" stroke="${LN}" stroke-width="4"/>`;
