  const two = (d) => `<path d="${d}" stroke="${LN}" stroke-width="13"/><path d="${d}" stroke="#fff" stroke-width="8"/>`;
  const bow = `<g fill="none" stroke-linecap="round" stroke-linejoin="round">${two("M-56 -228 Q-96 -272 -116 -246 Q-124 -222 -56 -228")}${two("M-56 -228 Q-36 -282 -6 -264 Q8 -244 -56 -228")}${two("M-56 -228 Q-48 -180 -30 -150")}${two("M-56 -228 Q-4 -206 30 -176")}</g><circle cx="-56" cy="-228" r="10" fill="#fff" stroke="${LN}" stroke-width="4"/>`;
