  const rings = SHOE.rings.map(([x, y]) => `<circle cx="${n2(x)}" cy="${n2(y)}" r="10" fill="${rg > .05 ? hexL("#C9D2DC", "#FFDD77", rg) : "url(#cSteel)"}" stroke="${hexL("#6E7A88", "#F59E0B", rg)}" stroke-width="3.5"/><circle cx="${n2(x)}" cy="${n2(y)}" r="3.6" fill="#4A5A66"/><path d="M${n2(x - 6)} ${n2(y - 4)} q4 -4 8 -2" fill="none" stroke="#fff" stroke-width="2.5" stroke-linecap="round"/>`).join("");
